# Every event type the service can append to an execution's event stream, in
# alphabetical order. The events query's type filter validates against this
# set; an unknown type is a validation error.
EVENT_TYPES = (
    "approval_decided",
    "approval_requested",
    "condition_evaluated",
    "execution_completed",
